import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { ConsultantUserSelection } from './ExpertCalculationReview';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';

export interface ConsultantUserRow extends ConsultantUserSelection {
  role: string;
  openRequired: number;
  ready: boolean;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

const ExpertUserList: React.FC<{
  onSelect: (user: ConsultantUserRow) => void;
}> = ({ onSelect }) => {
  const [users, setUsers] = useState<ConsultantUserRow[]>([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [downloadingId, setDownloadingId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/users'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setUsers(response.data?.data?.users || []);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load users.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const downloadRows = async (user: ConsultantUserRow) => {
    if (!user.msmeId) return;
    setDownloadingId(user.msmeId);
    setError(null);
    try {
      await downloadUncertainWorkbook(user.msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloadingId(null);
    }
  };

  const visible = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return users;
    return users.filter((user) => (
      user.name.toLowerCase().includes(needle)
      || user.email.toLowerCase().includes(needle)
      || user.companyName.toLowerCase().includes(needle)
    ));
  }, [query, users]);

  return (
    <Paper sx={{ p: 2, mb: 3 }}>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
        Choose a user
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Every MSME and enterprise user is listed here. Choose one to see that user&apos;s uncertain transactions, correct the carbon parameters, and approve them. Analytics and report generation for that user then use the approved calculation.
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      <TextField
        size="small"
        label="Find a user"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        sx={{ mb: 2, maxWidth: 360 }}
      />
      {loading ? <Typography variant="body2">Loading users…</Typography> : null}
      {!loading && users.length === 0 ? (
        <Typography variant="body2">No users are available for consultant review.</Typography>
      ) : null}
      {visible.length > 0 ? (
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>User</TableCell>
                <TableCell>Company</TableCell>
                <TableCell align="right">Uncertain transactions</TableCell>
                <TableCell>Report</TableCell>
                <TableCell />
              </TableRow>
            </TableHead>
            <TableBody>
              {visible.map((user) => (
                <TableRow key={`${user.userId}-${user.msmeId || 'none'}`}>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>{user.name}</Typography>
                    <Typography variant="caption" color="text.secondary">{user.email}</Typography>
                  </TableCell>
                  <TableCell>{user.companyName || 'No company ledger'}</TableCell>
                  <TableCell align="right">
                    {user.msmeId
                      ? `${user.openRequired} open · ${user.counts.withoutCalculation} without calculation · ${user.counts.spendBased} spend-based`
                      : '—'}
                  </TableCell>
                  <TableCell>
                    {!user.msmeId ? 'No ledger' : (user.ready ? 'Can generate' : 'Waiting for approval')}
                  </TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={!user.msmeId || downloadingId === user.msmeId}
                        onClick={() => { void downloadRows(user); }}
                      >
                        {downloadingId === user.msmeId ? 'Downloading' : 'Download uncertain rows'}
                      </Button>
                      <Button
                        size="small"
                        variant="contained"
                        disabled={!user.msmeId}
                        onClick={() => onSelect(user)}
                      >
                        {`Review ${user.name}`}
                      </Button>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Box>
      ) : null}
    </Paper>
  );
};

export default ExpertUserList;
