import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Chip,
  MenuItem,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';
import {
  REVIEW_CATEGORIES,
  categoryLabel,
  formatVoucherDate,
  groupByCategory,
} from './expertReviewCategories';

interface CompanySummary {
  msmeId: string;
  companyName: string;
  scope: 'required' | 'all';
  openRequired: number;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
  open: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

interface ReviewRow {
  _id: string;
  date?: string;
  description?: string;
  amount?: number;
  currency?: string;
  category?: string;
  subcategory?: string;
  quantity?: number;
  unit?: string;
  vendorName?: string;
  calculationClass?: string;
  formula?: string;
  co2Emissions?: number;
  quantificationMethod?: string;
  factorId?: string;
  factor?: number | null;
  factorUnit?: string;
  recommendation?: CorrectionRecommendation | null;
  settled?: boolean;
  settledKilograms?: number;
  priorKilograms?: number;
  informationRequest?: InformationRequest | null;
}

interface InformationRequest {
  status: 'open' | 'answered';
  kind: 'details' | 'bill';
  question: string;
  reply?: string;
  documentName?: string;
}

interface CorrectionRecommendation {
  id?: string;
  title: string;
  action: string;
  category?: string;
  unit?: string;
  quantity?: number | null;
  factorId?: string;
  factorLabel?: string;
  why?: string;
}

interface CorrectionAssistance {
  transactionId?: string;
  needsAssistance: boolean;
  referToRecommendation: boolean;
  message: string;
  apply?: {
    category?: string;
    quantity?: number | null;
    unit?: string;
    factorId?: string;
    factorLabel?: string;
  } | null;
}

const classLabel = (row: ReviewRow) => {
  const method = String(row.quantificationMethod || '').toLowerCase();
  const formula = String(row.formula || '');
  if (
    method.includes('admin_emission_review')
    || formula === 'adminEmissionReview'
    || row.factorId === 'activity_classification_required'
  ) {
    return 'Needs expert review';
  }
  if (row.calculationClass === 'spend_based') return 'Spend-based';
  if (row.calculationClass === 'calculated') return 'With calculation';
  return 'Without calculation';
};

const formulaLabel = (formula?: string) => {
  if (!formula || formula === 'adminEmissionReview') return 'Waiting for a named activity';
  if (formula === 'activityQuantity * emissionFactor') return 'Quantity × emission factor';
  if (formula === '(spendAmount / unitPrice) * emissionFactor') return 'Rupees ÷ unit price × emission factor';
  if (formula === '0') return 'Result is 0 kg CO2e';
  return formula;
};

const factorNeedsActivity = (factorId?: string) => (
  !factorId
  || factorId === 'spend_generic'
  || factorId === 'activity_classification_required'
);

const uncertaintyRank = (row: ReviewRow) => {
  if (classLabel(row) === 'Needs expert review') return 0;
  const recommendationId = String(row.recommendation?.id || '');
  if (row.category === 'maintenance' || /maintenance|refrigerant/.test(recommendationId)) return 1;
  if (row.calculationClass === 'spend_based' || classLabel(row) === 'Spend-based') return 2;
  return 3;
};

const lacksActivityQuantity = (row: ReviewRow) => {
  const quantity = Number(row.quantity);
  const kilograms = Number(row.co2Emissions || 0);
  return !row.settled && !(kilograms > 0) && !(Number.isFinite(quantity) && quantity > 0);
};

const suggestedText = (row: ReviewRow) => {
  const suggested = row.recommendation;
  if (!suggested) return '';
  const quantity = suggested.quantity == null ? '—' : String(suggested.quantity);
  return [
    `Suggested category ${categoryLabel(suggested.category)}`,
    `Suggested quantity ${quantity}`,
    `Suggested unit ${suggested.unit || '—'}`,
    suggested.factorLabel ? `Suggested factor ${suggested.factorLabel}` : '',
  ].filter(Boolean).join(' · ');
};

export interface ConsultantUserSelection {
  userId: string;
  name: string;
  email: string;
  companyName: string;
  msmeId: string;
}

const approvalEffect = (name?: string) => (
  name
    ? `Analytics and report generation for ${name} now use this calculation.`
    : 'Analytics and report generation for this user now use this calculation.'
);

const ExpertCalculationReview: React.FC<{
  selectedUser?: ConsultantUserSelection;
  onBack?: () => void;
}> = ({ selectedUser, onBack }) => {
  const [companies, setCompanies] = useState<CompanySummary[]>([]);
  const [msmeId, setMsmeId] = useState(selectedUser?.msmeId || '');
  const [rows, setRows] = useState<ReviewRow[]>([]);
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [downloading, setDownloading] = useState(false);
  const [assistanceById, setAssistanceById] = useState<Record<string, CorrectionAssistance>>({});
  const [askingId, setAskingId] = useState<string | null>(null);
  const token = () => localStorage.getItem('token');
  const groups = useMemo(() => groupByCategory(rows)
    .map((group) => ({
      ...group,
      rows: [...group.rows].sort((left, right) => uncertaintyRank(left) - uncertaintyRank(right)),
    }))
    .sort((left, right) => (
      uncertaintyRank(left.rows[0]) - uncertaintyRank(right.rows[0])
      || left.label.localeCompare(right.label)
    )), [rows]);
  const openRows = rows.filter((row) => !row.settled);
  const bulkBlocked = openRows.some(lacksActivityQuantity);

  const loadCompanies = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
      });
      const list = response.data?.data?.companies || [];
      setCompanies(list);
      setMsmeId((current) => selectedUser?.msmeId || current || list[0]?.msmeId || '');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load companies waiting for review.');
    } finally {
      setLoading(false);
    }
  }, [selectedUser?.msmeId]);

  const loadRows = useCallback(async (companyId: string) => {
    if (!companyId) {
      setRows([]);
      return;
    }
    try {
      const response = await axios.get(buildApiUrl('/expert/calculation-review'), {
        headers: { Authorization: `Bearer ${token()}` },
        params: { msmeId: companyId },
      });
      setRows(response.data?.data?.transactions || []);
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load the company review.');
    }
  }, []);

  useEffect(() => {
    void loadCompanies();
  }, [loadCompanies]);

  useEffect(() => {
    void loadRows(msmeId);
  }, [loadRows, msmeId]);

  const confirmOne = async (row: ReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/calculation-review/confirm`),
        { note },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const kilograms = Number(row.co2Emissions || 0);
      setNotice(`Approved ${row.description || 'the voucher'} in ${categoryLabel(row.category)}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`);
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? { ...item, settled: true, settledKilograms: kilograms }
          : item
      )));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The confirmation could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const correctOne = async (row: ReviewRow, draft: { category: string; quantity: string; unit: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/emission-review`),
        {
          category: draft.category,
          subcategory: row.subcategory || '',
          quantity: Number(draft.quantity),
          unit: draft.unit,
          note: note || 'Corrected by the expert consultant.',
        },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const saved = response.data?.data;
      const kilograms = Number(saved?.co2Emissions || 0);
      setNotice(
        `Corrected and approved ${row.description || 'the voucher'} in ${categoryLabel(draft.category)}. `
        + `Factor ${saved?.factorId || 'applied'}. ${kilograms} kg CO2e. ${approvalEffect(selectedUser?.name)}`
      );
      setRows((current) => current.map((item) => (
        item._id === row._id
          ? {
            ...item,
            settled: true,
            settledKilograms: kilograms,
            priorKilograms: Number(item.co2Emissions || 0),
            factorId: saved?.factorId || item.factorId,
            category: draft.category,
            quantity: Number(draft.quantity),
            unit: draft.unit,
          }
          : item
      )));
      await loadCompanies();
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The correction could not be saved.');
    } finally {
      setBusyId(null);
    }
  };

  const confirmOpen = async (category?: string) => {
    if (!msmeId) return;
    setBusyId(category || 'all');
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl('/expert/calculation-review/confirm-open'),
        { msmeId, note, category: category || undefined },
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice(response.data?.message || 'Open rows confirmed.');
      await loadCompanies();
      await loadRows(msmeId);
    } catch (saveError: any) {
      setError(saveError?.response?.data?.message || 'The open rows could not be confirmed.');
    } finally {
      setBusyId(null);
    }
  };

  const askCompany = async (row: ReviewRow, request: { kind: 'details' | 'bill'; question: string }) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request`),
        request,
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const informationRequest = response.data?.data?.informationRequest;
      setNotice(response.data?.message || 'Asked the company for more information.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be sent.');
    } finally {
      setBusyId(null);
    }
  };

  const cancelRequest = async (row: ReviewRow) => {
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/information-request/cancel`),
        {},
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      setNotice('The request was cancelled. You can correct this row.');
      setRows((current) => current.map((item) => (
        item._id === row._id ? { ...item, informationRequest: null } : item
      )));
    } catch (requestError: any) {
      setError(requestError?.response?.data?.message || 'The request could not be cancelled.');
    } finally {
      setBusyId(null);
    }
  };

  const askAgent = async (row: ReviewRow) => {
    setAskingId(row._id);
    setError(null);
    try {
      const response = await axios.post(
        buildApiUrl(`/expert/transactions/${row._id}/correction-assistance`),
        {},
        { headers: { Authorization: `Bearer ${token()}` } },
      );
      const assistance = response.data?.data?.assistance?.[0];
      if (!assistance) {
        setError('The correction agent did not return a recommendation.');
        return;
      }
      setAssistanceById((current) => ({ ...current, [row._id]: assistance }));
    } catch (assistError: any) {
      setError(assistError?.response?.data?.message || 'The correction agent could not be reached.');
    } finally {
      setAskingId(null);
    }
  };

  const downloadRows = async () => {
    if (!msmeId) return;
    setDownloading(true);
    setError(null);
    try {
      await downloadUncertainWorkbook(msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloading(false);
    }
  };

  const selected = companies.find((company) => company.msmeId === msmeId);

  return (
    <Paper sx={{ p: 2, mb: 3 }}>
      {onBack ? (
        <Button size="small" sx={{ mb: 1 }} onClick={onBack}>All users</Button>
      ) : null}
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
        {selectedUser ? `Uncertain transactions for ${selectedUser.name}` : 'Calculation review by category'}
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {selectedUser
          ? `${selectedUser.email}${selectedUser.companyName ? ` · ${selectedUser.companyName}` : ''}. When a row needs help, ask the correction agent and refer to its recommendation before changing the category, quantity, or unit. Analytics and report generation for this user use the approved calculation. Rupees are not multiplied by 0.001 kg CO2e per INR.`
          : 'Each category is a separate group. When a row needs help, ask the correction agent and refer to its recommendation, then apply that category, quantity, and unit. A correction recalculates the factor and the emissions. Rupees are not multiplied by 0.001 kg CO2e per INR.'}
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {loading ? <Typography variant="body2">Loading uncertain transactions…</Typography> : null}
      {selectedUser && !selectedUser.msmeId ? (
        <Typography variant="body2">This user has no company ledger, so there are no transactions to correct.</Typography>
      ) : null}
      {!selectedUser && !loading && companies.length === 0 ? (
        <Typography variant="body2">No company ledger is waiting for a calculation review.</Typography>
      ) : null}
      {!selectedUser && companies.length > 0 ? (
        <Box sx={{ display: 'grid', gap: 1, mb: 2 }}>
          <TextField
            select
            size="small"
            label="Company"
            value={msmeId}
            onChange={(event) => setMsmeId(event.target.value)}
          >
            {companies.map((company) => (
              <MenuItem key={company.msmeId} value={company.msmeId}>
                {`${company.companyName} · ${company.openRequired} open · ${company.counts.withoutCalculation} without calculation · ${company.counts.spendBased} spend-based`}
              </MenuItem>
            ))}
          </TextField>
          {selected ? (
            <Typography variant="body2" color="text.secondary">
              {selected.scope === 'all'
                ? 'This company also asked for review of transactions that already have a calculation.'
                : 'Required review covers rows without a calculation and spend-based rows.'}
            </Typography>
          ) : null}
        </Box>
      ) : null}
      {(selectedUser?.msmeId || (!selectedUser && companies.length > 0)) ? (
        <Box sx={{ display: 'grid', gap: 1, mb: 2 }}>
          <TextField
            size="small"
            label="Note for this review"
            value={note}
            onChange={(event) => setNote(event.target.value)}
          />
          <Button variant="outlined" disabled={!msmeId || downloading} onClick={() => { void downloadRows(); }}>
            {downloading ? 'Downloading' : 'Download this user’s uncertain rows'}
          </Button>
          {bulkBlocked ? (
            <Typography variant="body2" color="text.secondary">
              Enter a quantity on each row that is still at 0 kg CO2e. Those rows are not approved together.
            </Typography>
          ) : null}
          <Button
            variant="outlined"
            disabled={!msmeId || busyId === 'all' || openRows.length === 0 || bulkBlocked}
            onClick={() => { void confirmOpen(); }}
          >
            {busyId === 'all' ? 'Approving' : 'Approve all uncertain rows'}
          </Button>
        </Box>
      ) : null}
      {groups.length > 0 ? (
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
          {groups.map((group) => (
            <Chip key={group.key} label={`${group.label} · ${group.rows.length}`} color="primary" variant="outlined" />
          ))}
        </Box>
      ) : null}
      {groups.map((group) => (
        <Accordion key={group.key} defaultExpanded disableGutters>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
              <Typography sx={{ fontWeight: 700 }}>{group.label}</Typography>
              <Chip size="small" label={`${group.rows.length} open`} />
            </Box>
          </AccordionSummary>
          <AccordionDetails>
            <Button
              size="small"
              variant="outlined"
              sx={{ mb: 1 }}
              disabled={busyId === group.key || group.rows.some(lacksActivityQuantity)}
              onClick={() => { void confirmOpen(group.key); }}
            >
              {busyId === group.key ? 'Approving' : `Approve ${group.label}`}
            </Button>
            {group.rows.map((row) => (
              <ReviewRowEditor
                key={row._id}
                row={row}
                busy={busyId === row._id}
                assistance={assistanceById[row._id]}
                asking={askingId === row._id}
                onAskAgent={() => { void askAgent(row); }}
                onAskCompany={(request) => { void askCompany(row, request); }}
                onCancelRequest={() => { void cancelRequest(row); }}
                onConfirm={() => { void confirmOne(row); }}
                onCorrect={(draft) => { void correctOne(row, draft); }}
              />
            ))}
          </AccordionDetails>
        </Accordion>
      ))}
      {!loading && msmeId && rows.length === 0 ? (
        <Typography variant="body2">No open rows for this company.</Typography>
      ) : null}
    </Paper>
  );
};

const ReviewRowEditor: React.FC<{
  row: ReviewRow;
  busy: boolean;
  assistance?: CorrectionAssistance;
  asking?: boolean;
  onAskAgent: () => void;
  onAskCompany: (request: { kind: 'details' | 'bill'; question: string }) => void;
  onCancelRequest: () => void;
  onConfirm: () => void;
  onCorrect: (draft: { category: string; quantity: string; unit: string }) => void;
}> = ({ row, busy, assistance, asking = false, onAskAgent, onAskCompany, onCancelRequest, onConfirm, onCorrect }) => {
  const suggested = row.recommendation;
  const [category, setCategory] = useState(suggested?.category || row.category || 'other');
  const [quantity, setQuantity] = useState(
    suggested
      ? (suggested.quantity != null ? String(suggested.quantity) : '')
      : (row.quantity != null ? String(row.quantity) : '')
  );
  const [unit, setUnit] = useState(suggested ? (suggested.unit || '') : (row.unit || ''));
  const [question, setQuestion] = useState('');
  const request = row.informationRequest;
  const waiting = request?.status === 'open';
  const needsActivity = factorNeedsActivity(row.factorId);
  const factorLine = needsActivity
    ? 'No activity factor yet. Emissions stay at 0 kg CO2e until you name the activity.'
    : `Factor ${row.factorId}${row.factor != null ? ` · ${row.factor} ${row.factorUnit || ''}`.trim() : ''}`;
  const when = formatVoucherDate(row.date);

  return (
    <Box sx={{ borderTop: 1, borderColor: 'divider', py: 2 }}>
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap', mb: 0.5 }}>
        <Typography variant="subtitle2">{row.description || 'Untitled voucher'}</Typography>
        <Chip size="small" label={classLabel(row)} />
      </Box>
      <Typography variant="body2" color="text.secondary">
        {[
          when,
          row.vendorName,
          row.amount != null ? `${row.amount} ${row.currency || 'INR'}` : 'No amount',
          row.subcategory ? `Subcategory ${row.subcategory}` : '',
        ].filter(Boolean).join(' · ')}
      </Typography>
      <Typography variant="body2" sx={{ mt: 0.5 }}>
        {`Before ${Number(row.priorKilograms ?? row.co2Emissions) || 0} kg CO2e · ${factorLine} · ${formulaLabel(row.formula)}`}
      </Typography>
      {suggestedText(row) ? (
        <Typography variant="body2" sx={{ mt: 0.5 }}>{suggestedText(row)}</Typography>
      ) : null}
      {row.settled ? (
        <Alert severity="success" sx={{ mt: 1 }}>
          {`Approved. ${Number(row.settledKilograms ?? row.co2Emissions) || 0} kg CO2e.`}
        </Alert>
      ) : null}
      {suggested && !row.settled && !assistance ? (
        <Alert severity="info" sx={{ mt: 1 }}>
          <Typography variant="subtitle2">{suggested.title}</Typography>
          <Typography variant="body2">{suggested.action}</Typography>
        </Alert>
      ) : null}
      {assistance && !row.settled ? (
        <Alert severity={assistance.referToRecommendation ? 'info' : 'success'} sx={{ mt: 1 }}>
          <Typography variant="subtitle2">
            {assistance.referToRecommendation ? 'Refer to this recommendation' : 'No parameter change is recommended'}
          </Typography>
          <Typography variant="body2">{assistance.message}</Typography>
          {assistance.apply?.factorLabel ? (
            <Typography variant="body2" sx={{ mt: 0.5 }}>{`Suggested factor ${assistance.apply.factorLabel}`}</Typography>
          ) : null}
        </Alert>
      ) : null}
      {request && !row.settled ? (
        <Alert severity={waiting ? 'warning' : 'info'} sx={{ mt: 1 }}>
          <Typography variant="subtitle2">
            {request.kind === 'bill' ? 'Asked the company to upload the bill' : 'Asked the company for more information'}
          </Typography>
          <Typography variant="body2">{request.question}</Typography>
          {request.status === 'answered' ? (
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              {`Company reply: ${request.reply || 'No written reply.'}${request.documentName ? ` Bill: ${request.documentName}.` : ''}`}
            </Typography>
          ) : (
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              Carbon stays unchanged until the company replies. Then review the reply and correct the calculation.
            </Typography>
          )}
        </Alert>
      ) : null}
      {row.settled || waiting ? null : (
      <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.4fr 0.7fr 0.7fr auto auto' }, gap: 1, mt: 1 }}>
        <TextField select size="small" label="Category" value={REVIEW_CATEGORIES.includes(category as typeof REVIEW_CATEGORIES[number]) ? category : 'other'} onChange={(event) => setCategory(event.target.value)}>
          {REVIEW_CATEGORIES.map((item) => <MenuItem key={item} value={item}>{categoryLabel(item)}</MenuItem>)}
        </TextField>
        <TextField size="small" label="Quantity" value={quantity} onChange={(event) => setQuantity(event.target.value)} />
        <TextField size="small" label="Unit" value={unit} placeholder="kg, L, kWh" onChange={(event) => setUnit(event.target.value)} />
        <Button variant="outlined" disabled={busy || asking} onClick={onAskAgent}>
          {asking ? 'Asking the agent' : 'Ask the correction agent'}
        </Button>
        {assistance?.apply ? (
          <Button
            variant="outlined"
            disabled={busy}
            onClick={() => {
              const apply = assistance.apply;
              if (!apply) return;
              if (apply.category) setCategory(apply.category);
              if (apply.unit) setUnit(apply.unit);
              if (apply.quantity != null) setQuantity(String(apply.quantity));
            }}
          >
            Use this recommendation
          </Button>
        ) : null}
        <Button variant="outlined" disabled={busy} onClick={onConfirm}>Approve</Button>
        <Button
          variant="contained"
          disabled={busy || quantity === '' || !unit}
          onClick={() => onCorrect({ category, quantity, unit })}
        >
          Correct and approve
        </Button>
      </Box>
      )}
      {row.settled ? null : (
        <Box sx={{ display: 'grid', gap: 1, mt: 1 }}>
          {waiting ? (
            <Button variant="text" disabled={busy} onClick={onCancelRequest}>Cancel this request</Button>
          ) : (
            <>
              <TextField
                size="small"
                label="What is missing"
                value={question}
                placeholder="The bill does not show the diesel litres"
                onChange={(event) => setQuestion(event.target.value)}
              />
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                <Button
                  variant="outlined"
                  disabled={busy || question.trim().length < 8}
                  onClick={() => onAskCompany({ kind: 'details', question: question.trim() })}
                >
                  Ask for more information
                </Button>
                <Button
                  variant="outlined"
                  disabled={busy || question.trim().length < 8}
                  onClick={() => onAskCompany({ kind: 'bill', question: question.trim() })}
                >
                  Ask for the bill
                </Button>
              </Box>
            </>
          )}
        </Box>
      )}
    </Box>
  );
};

export default ExpertCalculationReview;
