import React from 'react';
import {
  AppBar,
  Box,
  Button,
  Chip,
  Container,
  Stack,
  Toolbar,
  Typography,
} from '@mui/material';
import { Logout as LogoutIcon } from '@mui/icons-material';
import BrandLogoMark from '../BrandLogoMark';
import { getPortalRoleLabel } from '../../constants/adminPortal';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import { useRegistration } from '../../context/RegistrationContext';

interface ExpertPortalLayoutProps {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}

const ExpertPortalLayout: React.FC<ExpertPortalLayoutProps> = ({
  title,
  subtitle,
  children,
}) => {
  const { logout } = useRegistration();
  const portalUser = getAdminPortalUser();
  const displayName = [portalUser?.profile?.firstName, portalUser?.profile?.lastName]
    .filter(Boolean)
    .join(' ')
    .trim();

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'grey.100' }}>
      <AppBar position="static" color="default" elevation={1}>
        <Toolbar sx={{ gap: 2, flexWrap: 'wrap', py: 1 }}>
          <BrandLogoMark width={180} />
          <Box sx={{ flexGrow: 1, minWidth: 200 }}>
            <Typography variant="subtitle2" color="text.secondary">
              Expert consultant
            </Typography>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>
              {displayName || portalUser?.email || 'Signed in'}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Chip
              size="small"
              color="secondary"
              label={getPortalRoleLabel(portalUser?.role)}
            />
            <Button
              size="small"
              color="inherit"
              startIcon={<LogoutIcon />}
              onClick={() => logout({ redirectTo: '/login' })}
            >
              Logout
            </Button>
          </Stack>
        </Toolbar>
      </AppBar>

      <Container maxWidth="xl" sx={{ py: 4 }}>
        <Box sx={{ mb: 3 }}>
          <Typography component="h1" variant="h4" sx={{ fontWeight: 700 }}>
            {title}
          </Typography>
          {subtitle ? (
            <Typography variant="body1" color="text.secondary" sx={{ mt: 0.5 }}>
              {subtitle}
            </Typography>
          ) : null}
        </Box>
        {children}
      </Container>
    </Box>
  );
};

export default ExpertPortalLayout;
