import React, { useState } from 'react';
import ExpertPortalLayout from './ExpertPortalLayout';
import ExpertCalculationReview from './ExpertCalculationReview';
import ExpertUserList, { ConsultantUserRow } from './ExpertUserList';

const ExpertDashboard: React.FC = () => {
  const [user, setUser] = useState<ConsultantUserRow | null>(null);

  return (
    <ExpertPortalLayout
      title="Consultant review"
      subtitle={user
        ? 'Correct the carbon parameters on this user\u2019s uncertain transactions, then approve them. Analytics and report generation for this user use the approved calculation.'
        : 'Choose a user first. Uncertain transactions for that user are the next step. Approve a corrected calculation before that user generates a report.'}
    >
      {user ? (
        <ExpertCalculationReview
          selectedUser={user}
          onBack={() => setUser(null)}
        />
      ) : (
        <ExpertUserList onSelect={setUser} />
      )}
    </ExpertPortalLayout>
  );
};

export default ExpertDashboard;
